import { readFile } from 'node:fs/promises';
import { z } from 'zod';

export const HUB_REPOSITORY = 'lucaseduardocrp/agent-devkit-hub';
/** Generated by the ADK Hub repository on every change to its main branch. */
export const DEFAULT_HUB_URL = `https://raw.githubusercontent.com/${HUB_REPOSITORY}/main/index.json`;

const name = z.string().regex(/^[a-z0-9]+(?:-[a-z0-9]+)*$/);
const sha = z.string().regex(/^[0-9a-f]{40}$/);
// Plain relative POSIX paths only: no `..`, no absolute paths, no backslashes.
const relativePath = z
  .string()
  .regex(/^[A-Za-z0-9_-][A-Za-z0-9._-]*(?:\/[A-Za-z0-9_-][A-Za-z0-9._-]*)*$/)
  .refine((path) => !path.split('/').includes('..'));

const categorySchema = z.object({
  id: z.string(),
  icon: z.string(),
  label: z.record(z.string(), z.string()),
});

const skillSchema = z.object({
  name,
  description: z.string(),
  overview: z.string().default(''),
  category: z.string(),
  tags: z.array(z.string()).default([]),
  toolsets: z.array(z.string()).default([]),
  author: z.string(),
  version: z.string(),
  license: z.string(),
  tier: z.enum(['built-in', 'official', 'community']),
  path: relativePath,
  /** Set when the skill lives outside the hub repository (built-in skills live in ADK). */
  repository: z
    .string()
    .regex(/^[\w.-]+\/[\w.-]+$/)
    .optional(),
  commit: sha.optional(),
  files: z
    .array(
      z.object({
        path: relativePath,
        size: z.number().int().nonnegative(),
        sha256: z.string().regex(/^[0-9a-f]{64}$/),
      }),
    )
    .min(1),
});

const pluginSchema = z.object({
  name,
  title: z.string(),
  description: z.string(),
  repo: z.url({ protocol: /^https$/ }),
  sha,
  subdir: z.union([z.literal(''), relativePath]),
  version: z.string().optional(),
  maintainer: z.string(),
  tier: z.enum(['official', 'verified', 'community']),
  category: z.string(),
  license: z.string(),
  homepage: z.string().optional(),
  image: z.string().optional(),
  platforms: z.array(z.enum(['linux', 'macos', 'windows'])).default([]),
  requiresDevkit: z.string().optional(),
  disclosure: z.string().optional(),
  capabilities: z.object({
    skills: z.array(name),
    agents: z.array(name),
    mcpServers: z.array(z.string()),
    requiresEnv: z.array(z.string()),
  }),
});

const indexSchema = z.object({
  schemaVersion: z.literal(1),
  repository: z.string().regex(/^[\w.-]+\/[\w.-]+$/),
  commit: sha,
  generatedAt: z.string(),
  categories: z.object({ skills: z.array(categorySchema), plugins: z.array(categorySchema) }),
  skills: z.array(skillSchema),
  plugins: z.array(pluginSchema),
  removed: z.array(
    z.object({
      name: z.string(),
      repo: z.string().optional(),
      reason: z.string(),
      date: z.string(),
    }),
  ),
});

export type HubIndex = z.infer<typeof indexSchema>;
export type HubSkill = z.infer<typeof skillSchema>;
export type HubPlugin = z.infer<typeof pluginSchema>;
export type HubKind = 'skill' | 'plugin';

/** Downloads (or reads, for a local path) the hub index and checks its shape. */
export async function fetchHubIndex(
  source = DEFAULT_HUB_URL,
  fetcher: typeof fetch = fetch,
): Promise<HubIndex> {
  let raw: unknown;
  if (/^https?:\/\//.test(source)) {
    const response = await fetcher(source, { signal: AbortSignal.timeout(30_000) });
    if (!response.ok)
      throw new Error(`Could not load the ADK Hub (${response.status} from ${source}).`);
    raw = await response.json();
  } else {
    raw = JSON.parse(await readFile(source, 'utf8'));
  }
  const parsed = indexSchema.safeParse(raw);
  if (!parsed.success) {
    throw new Error(
      `The ADK Hub index at ${source} is not in a format this devkit understands. Update devkit with "npm install -g @agent-devkit/cli".`,
    );
  }
  return parsed.data;
}

/**
 * Loads the index at the newest commit of the hub's main branch. raw.githubusercontent.com caches
 * branch URLs for 5 minutes but never changes a commit URL, so asking GitHub for the commit first
 * shows a merged skill within seconds. Falls back to the branch URL when the API cannot answer
 * (offline, or its hourly limit for anonymous calls was reached).
 */
export async function fetchLatestHubIndex(fetcher: typeof fetch = fetch): Promise<HubIndex> {
  let commit: string | undefined;
  try {
    const response = await fetcher(`https://api.github.com/repos/${HUB_REPOSITORY}/commits/main`, {
      headers: { accept: 'application/vnd.github.sha' },
      signal: AbortSignal.timeout(10_000),
    });
    const text = response.ok ? (await response.text()).trim() : '';
    if (/^[0-9a-f]{40}$/.test(text)) commit = text;
  } catch {
    // The branch URL below still works, at most five minutes behind.
  }
  if (commit) {
    try {
      return await fetchHubIndex(
        `https://raw.githubusercontent.com/${HUB_REPOSITORY}/${commit}/index.json`,
        fetcher,
      );
    } catch {
      // Same fallback.
    }
  }
  return fetchHubIndex(DEFAULT_HUB_URL, fetcher);
}

/** Repository and commit a skill's files come from: its own, or the hub's at index time. */
export function skillSource(
  index: HubIndex,
  skill: HubSkill,
): { repository: string; commit: string } {
  return { repository: skill.repository ?? index.repository, commit: skill.commit ?? index.commit };
}

/** URL of one skill file at the commit it is pinned to. */
export function skillFileUrl(index: HubIndex, skill: HubSkill, file: string): string {
  const { repository, commit } = skillSource(index, skill);
  return `https://raw.githubusercontent.com/${repository}/${commit}/${skill.path}/${file}`;
}

/** Why an item may not be installed, or undefined when it is allowed. */
export function removalReason(
  index: HubIndex,
  itemName: string,
  repo?: string,
): string | undefined {
  const normalized = repo?.replace(/\.git$/, '').toLowerCase();
  const hit = index.removed.find(
    (item) =>
      item.name === itemName ||
      (normalized && item.repo?.replace(/\.git$/, '').toLowerCase() === normalized),
  );
  return hit ? `${hit.name} was removed from the ADK Hub on ${hit.date}: ${hit.reason}` : undefined;
}

export function findItem(index: HubIndex, kind: 'skill', itemName: string): HubSkill;
export function findItem(index: HubIndex, kind: 'plugin', itemName: string): HubPlugin;
export function findItem(index: HubIndex, kind: HubKind, itemName: string): HubSkill | HubPlugin {
  const items: readonly (HubSkill | HubPlugin)[] = kind === 'skill' ? index.skills : index.plugins;
  const item = items.find((candidate) => candidate.name === itemName);
  if (item) return item;
  const close = search(index, kind, itemName)
    .slice(0, 3)
    .map((candidate) => candidate.name);
  throw new Error(
    `No ${kind} named "${itemName}" in the ADK Hub.${close.length ? ` Did you mean ${close.join(', ')}?` : ''}`,
  );
}

/** Items whose name, description, tags or category contain every word of the query. */
export function search(
  index: HubIndex,
  kind: HubKind,
  query = '',
  category?: string,
): readonly (HubSkill | HubPlugin)[] {
  const terms = query
    .toLowerCase()
    .split(/[\s,]+/)
    .filter(Boolean);
  const items: readonly (HubSkill | HubPlugin)[] = kind === 'skill' ? index.skills : index.plugins;
  return items.filter((item) => {
    if (category && item.category !== category) return false;
    const haystack = [
      item.name,
      item.description,
      item.category,
      'tags' in item ? item.tags.join(' ') : item.maintainer,
    ]
      .join(' ')
      .toLowerCase();
    return terms.every((term) => haystack.includes(term));
  });
}

/** True when `version` satisfies a `>=x.y[.z]` floor. Unknown formats never block an install. */
export function satisfiesFloor(version: string, floor: string | undefined): boolean {
  const required = floor?.match(/^>=(\d+)\.(\d+)(?:\.(\d+))?$/);
  const current = version.match(/^(\d+)\.(\d+)\.(\d+)/);
  if (!required || !current) return true;
  for (let part = 1; part <= 3; part += 1) {
    const a = Number(current[part]);
    const b = Number(required[part] ?? 0);
    if (a !== b) return a > b;
  }
  return true;
}
